import { expect, test, uniqueName } from "../../fixtures";

test.describe("Manage vendors", () => {
  test(
    "Create a vendor",
    { tag: "@VEN-01" },
    async ({ apiAs }) => {
      // Arrange
      const member = await apiAs("member");
      const name = uniqueName("Acme Freight");
      const contact = `ops+${Date.now().toString(36)}${Math.random().toString(36).slice(2, 6)}@acmefreight.example`;

      // Act
      const createResponse = await member.post("/api/vendors", {
        data: {
          name,
          category: "logistics",
          contact_email: contact,
        },
      });

      // Assert
      expect(createResponse.status()).toBe(201);
      const vendor = await createResponse.json();
      expect(vendor.name).toBe(name);
      expect(vendor.category).toBe("logistics");
      expect(vendor.status).toBe("draft");

      const auditResponse = await member.get(`/api/vendors/${vendor.id}/audit`);
      expect(auditResponse.status()).toBe(200);
      const trail = (await auditResponse.json()) as {
        items: { action: string }[];
      };
      expect(trail.items.map((event) => event.action)).toContain("vendor.created");
    },
  );
});
